settings.custom_liquid:
{%- liquid
  assign current_handle = collection.handle

  case current_handle
    when 'felt-festive-decorations', 'festive', 'festive-decorations', 'home-eco-living'
      assign badge_text = 'Handcrafted for the holidays'
    when 'felt-home-wares', 'homewares', 'home-wares'
      assign badge_text = 'Cosy, artisanal homewares'
    when 'felt-bags-and-purses', 'bags-and-purses', 'bags'
      assign badge_text = 'Ethical accessories'
    when 'felt-pet-play', 'pet-play', 'pets'
      assign badge_text = 'Eco-friendly pet living'
    else
      assign badge_text = 'Artisanal creations'
  endcase

  assign collection_intro = collection.description | strip_html | strip | truncatewords: 36
-%}

<div class="custom-collection-banner-wrapper everest-masthead">
  <div class="custom-collection-banner-container everest-masthead__inner">
    <p class="banner-badge everest-masthead__badge">{{ badge_text }}</p>
    <h1 class="collection-main-title everest-masthead__title">
      {{- collection.title | default: 'Felt Festive Decorations' | escape -}}
    </h1>
    {%- if collection_intro != blank -%}
      <p class="everest-masthead__intro">{{ collection_intro | escape }}</p>
    {%- endif -%}
    {%- if collection.products_count > 0 -%}
      <p class="everest-masthead__meta">
        {{ collection.products_count }} handmade
        {{ collection.products_count | pluralize: 'piece', 'pieces' }}, felted in Nepal from pure New Zealand wool
      </p>
    {%- endif -%}
  </div>
</div>

<style>
  /* Editorial masthead: left-aligned, large serif title, closed by a running stitch. */
  .everest-masthead {
    width: 100vw;
    position: relative;
    left: 50%;
    right: 50%;
    margin-left: -50vw;
    margin-right: -50vw;
    padding: clamp(40px, 7vw, 96px) 20px clamp(28px, 4vw, 48px);
    box-sizing: border-box;
    background: transparent;
  }

  .everest-masthead__inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }

  .everest-masthead__inner::after {
    content: "";
    align-self: stretch;
    height: 2px;
    margin-top: clamp(16px, 2.5vw, 28px);
    background: linear-gradient(90deg, #9B3654 60%, transparent 0) 0 0 / 15px 2px repeat-x;
    opacity: 0.7;
  }

  .everest-masthead__badge {
    margin: 0;
    font-family: var(--font-heading--family), Georgia, serif;
    font-style: italic;
    font-size: clamp(18px, 1.8vw, 22px);
    line-height: 1.2;
    color: #58182D;
  }

  .everest-masthead__title {
    margin: 0;
    font-family: var(--font-heading--family), Georgia, serif;
    font-weight: 400;
    font-size: clamp(44px, 7.2vw, 96px);
    line-height: 0.95;
    letter-spacing: -0.02em;
    color: #2B2421;
    text-wrap: balance;
  }

  .everest-masthead__intro {
    max-width: 60ch;
    margin: 6px 0 0;
    font-size: 17px;
    line-height: 1.6;
    color: rgb(43 36 33 / 0.82);
  }

  .everest-masthead__meta {
    margin: 0;
    font-size: 14px;
    line-height: 1.5;
    color: rgb(43 36 33 / 0.7);
  }

  @media (max-width: 768px) {
    .everest-masthead {
      padding-inline: 16px;
    }
  }
</style>

{% assign current_title = collection.title | downcase %}
{% assign current_handle = collection.handle | downcase %}

{% comment %} Show Coming Soon ONLY if it is NOT festive AND has no active products listed {% endcomment %}
{% unless current_title contains 'festive' or current_handle contains 'home-eco-living' or current_handle contains 'festive' or collection.all_products_count > 0 %}

  <div class="coming-soon-card-wrapper">
    <div class="coming-soon-card-container">

      <!-- Decorative Icon Badge -->
      <div class="coming-soon-badge">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#C05A67" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
          <circle cx="12" cy="12" r="10"></circle>
          <polyline points="12 6 12 12 16 14"></polyline>
        </svg>
      </div>

      <span class="coming-soon-tagline">Handcrafted Heritage In Production</span>

      <h2 class="coming-soon-title">
        {{ collection.title | default: "Artisanal Collection" }} — Coming Soon
      </h2>

      <p class="coming-soon-description">
        Our master women artisans in Kathmandu are currently hand-felting this new collection using 100% pure New Zealand wool and non-toxic Azo-free dyes. Stay tuned as we prepare these zero-waste creations for launch!
      </p>

      <!-- Sub-Pillars -->
      <div class="coming-soon-highlights">
        <span class="highlight-chip">❀ 100% Pure NZ Wool</span>
        <span class="highlight-chip">❀ Fair Trade Empowered</span>
        <span class="highlight-chip">❀ Zero-Waste & Natural</span>
      </div>

      <!-- Button pointing directly to live collection -->
      <div class="coming-soon-actions">
        <a href="/collections/home-eco-living" class="primary-btn">
          Explore Available Festive Ornaments
        </a>
      </div>

    </div>
  </div>

  <style>
    /* "Coming soon": a stitched felt label on a paper mat, in the same family as the size card. */
    .coming-soon-card-wrapper {
      width: 100%;
      padding: 24px 0 56px 0;
      display: flex;
      justify-content: center;
      align-items: center;
      box-sizing: border-box;
    }

    .coming-soon-card-container {
      max-width: 680px;
      width: 100%;
      background: #FCF9F4;
      border: 1px solid #E3D8C6;
      border-radius: 6px;
      outline: 1.5px dashed rgba(155, 54, 84, 0.5);
      outline-offset: -12px;
      padding: 52px 40px;
      text-align: center;
      box-sizing: border-box;
      margin: 0 auto;
    }

    .coming-soon-badge {
      width: 52px;
      height: 52px;
      background-color: #F7F2EA;
      border: 1px solid #E3D8C6;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 18px;
    }

    .coming-soon-badge svg {
      stroke: #58182D;
    }

    .coming-soon-tagline {
      font-family: var(--font-heading--family), Georgia, serif;
      font-style: italic;
      font-size: 18px;
      color: #58182D;
      display: block;
      margin-bottom: 10px;
    }

    .coming-soon-title {
      font-family: var(--font-heading--family), Georgia, serif;
      font-size: 40px;
      font-weight: 400;
      color: #2B2421;
      margin: 0 0 16px 0;
      line-height: 1.05;
      letter-spacing: -0.01em;
      text-wrap: balance;
    }

    .coming-soon-description {
      font-family: var(--font-body--family), system-ui, sans-serif;
      font-size: 15px;
      line-height: 1.65;
      color: rgb(43 36 33 / 0.8);
      max-width: 52ch;
      margin: 0 auto 24px;
    }

    .coming-soon-highlights {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px;
      margin-bottom: 30px;
    }

    .highlight-chip {
      background: transparent;
      color: #58182D;
      border: 1px solid #E3D8C6;
      padding: 6px 14px;
      border-radius: 999px;
      font-family: var(--font-body--family), system-ui, sans-serif;
      font-size: 13px;
      font-weight: 500;
    }

    .coming-soon-actions {
      display: flex;
      justify-content: center;
    }

    .primary-btn {
      display: inline-block;
      background-color: #58182D;
      color: #F7F2EA !important;
      font-family: var(--font-body--family), system-ui, sans-serif;
      font-size: 15px;
      font-weight: 600;
      padding: 14px 28px;
      border-radius: 2px;
      text-decoration: none;
      transition: background-color 0.25s ease;
    }

    .primary-btn:hover {
      background-color: #74233F;
    }

    .primary-btn:focus-visible {
      outline: 2px solid #58182D;
      outline-offset: 3px;
    }

    @media (max-width: 768px) {
      .coming-soon-card-wrapper {
        padding: 12px 0 32px 0;
      }

      .coming-soon-card-container {
        padding: 36px 22px;
        outline-offset: -8px;
      }

      .coming-soon-title {
        font-size: 30px;
      }

      .coming-soon-description {
        font-size: 14px;
      }
    }
  </style>

{% endunless %}
